#include <functional>
#include <iostream>
#include <cctype>

namespace oauth {

struct RedirectConfig {
    std::vector<std::string> allowed_schemes = {"https"};
    std::vector<std::string> allowed_domains;
    bool allow_subdomains = false;
    uint16_t default_port = 443;
};

class URLComponents {
public:
    std::string scheme;
    std::string userinfo;
    std::string host;
    uint16_t port;
    std::string path;
    std::string query;
    std::string fragment;

    static URLComponents parse(const std::string& url) {
        URLComponents c;
        std::string remaining = url;

        // Extract scheme
        auto scheme_end = remaining.find("://");
        if (scheme_end != std::string::npos) {
            c.scheme = remaining.substr(0, scheme_end);
            std::transform(c.scheme.begin(), c.scheme.end(), c.scheme.begin(), ::tolower);
            remaining = remaining.substr(scheme_end + 3);
        }

        // Extract fragment
        auto frag_pos = remaining.find('#');
        if (frag_pos != std::string::npos) {
            c.fragment = remaining.substr(frag_pos + 1);
            remaining = remaining.substr(0, frag_pos);
        }

        // Extract query
        auto query_pos = remaining.find('?');
        if (query_pos != std::string::npos) {
            c.query = remaining.substr(query_pos + 1);
            remaining = remaining.substr(0, query_pos);
        }

        // Extract userinfo
        auto at_pos = remaining.find('@');
        auto slash_pos = remaining.find('/');
        if (at_pos != std::string::npos && (slash_pos == std::string::npos || at_pos < slash_pos)) {
            c.userinfo = remaining.substr(0, at_pos);
            remaining = remaining.substr(at_pos + 1);
        }

        // Extract path
        slash_pos = remaining.find('/');
        if (slash_pos != std::string::npos) {
            c.path = remaining.substr(slash_pos);
            remaining = remaining.substr(0, slash_pos);
        }

        // Extract host and port
        auto colon_pos = remaining.rfind(':');
        if (colon_pos != std::string::npos && remaining.find(']') == std::string::npos) {
            c.host = remaining.substr(0, colon_pos);
            try {
                c.port = static_cast<uint16_t>(std::stoi(remaining.substr(colon_pos + 1)));
            } catch (...) {
                c.host = remaining;
                c.port = 0;
            }
        } else {
            c.host = remaining;
            c.port = 0;
        }

        std::transform(c.host.begin(), c.host.end(), c.host.begin(), ::tolower);
        return c;
    }
};

class RedirectValidator {
private:
    RedirectConfig config_;

    std::string normalize_host(const std::string& host) const {
        std::string normalized = host;
        // Strip trailing dots (FQDN normalization)
        while (!normalized.empty() && normalized.back() == '.') {
            normalized.pop_back();
        }
        return normalized;
    }

    bool domain_matches(const std::string& candidate, const std::string& allowed) const {
        std::string norm_candidate = normalize_host(candidate);
        std::string norm_allowed = normalize_host(allowed);

        if (norm_candidate == norm_allowed) return true;

        if (config_.allow_subdomains) {
            std::string suffix = "." + norm_allowed;
            if (norm_candidate.length() > suffix.length()) {
                return norm_candidate.compare(
                    norm_candidate.length() - suffix.length(),
                    suffix.length(), suffix) == 0;
            }
        }
        return false;
    }

    // Decode percent-encoded characters for normalization.
    // Validates hex digits before decoding to avoid exceptions (DoS) on
    // malformed input; invalid sequences are passed through literally.
    std::string percent_decode(const std::string& input) const {
        auto is_hex = [](char ch) {
            return std::isxdigit(static_cast<unsigned char>(ch)) != 0;
        };

        std::string output;
        for (size_t i = 0; i < input.length(); i++) {
            if (input[i] == '%' && i + 2 <= input.length() - 1 &&
                is_hex(input[i + 1]) && is_hex(input[i + 2])) {
                std::string hex = input.substr(i + 1, 2);
                unsigned int value = 0;
                std::istringstream iss(hex);
                iss >> std::hex >> value;
                if (!iss.fail()) {
                    output += static_cast<char>(value & 0xFF);
                    i += 2;
                    continue;
                }
                // Fall through: treat '%' literally if parse failed.
                output += input[i];
            } else {
                output += input[i];
            }
        }
        return output;
    }

    // Resolve path traversal sequences
    std::string normalize_path(const std::string& path) const {
        std::string decoded = percent_decode(path);
        std::vector<std::string> segments;
        std::istringstream stream(decoded);
        std::string segment;

        while (std::getline(stream, segment, '/')) {
            if (segment == "..") {
                if (!segments.empty()) segments.pop_back();
            } else if (segment != "." && !segment.empty()) {
                segments.push_back(segment);
            }
        }

        std::string result = "/";
        for (size_t i = 0; i < segments.size(); i++) {
            result += segments[i];
            if (i < segments.size() - 1) result += "/";
        }
        return result;
    }

public:
    explicit RedirectValidator(const RedirectConfig& config) : config_(config) {}

    struct ValidationResult {
        bool valid;
        std::string sanitized_url;
        std::string error;
    };

    ValidationResult validate_redirect_uri(const std::string& redirect_uri,
                                           const std::map<std::string, std::string>& proxy_headers) const {
        ValidationResult result{false, "", ""};

        std::string effective_uri = redirect_uri;

        URLComponents components = URLComponents::parse(effective_uri);

        // Do NOT trust proxy headers for redirect URI validation.
        // The redirect_uri must be validated as-is from the client request.
        // Proxy headers are only used for logging/auditing, never for security decisions.
        (void)proxy_headers;

        // Validate scheme
        if (std::find(config_.allowed_schemes.begin(), config_.allowed_schemes.end(),
                      components.scheme) == config_.allowed_schemes.end()) {
            result.error = "Invalid scheme: " + components.scheme;
            return result;
        }

        // Reject userinfo component (potential credential stuffing in URL)
        if (!components.userinfo.empty()) {
            result.error = "Userinfo component not allowed";
            return result;
        }

        // Validate host against allowlist
        bool host_valid = false;
        for (const auto& allowed : config_.allowed_domains) {
            if (domain_matches(components.host, allowed)) {
                host_valid = true;
                break;
            }
        }

        if (!host_valid) {
            result.error = "Host not in allowlist: " + components.host;
            return result;
        }

        // Normalize and validate path
        std::string norm_path = normalize_path(components.path);

        // Reconstruct sanitized URL - always use the validated components
        std::ostringstream sanitized;
        sanitized << components.scheme << "://" << components.host;
        if (components.port != 0 && components.port != config_.default_port) {
            sanitized << ":" << components.port;
        }
        sanitized << norm_path;
        if (!components.query.empty()) {
            sanitized << "?" << components.query;
        }

        result.valid = true;
        result.sanitized_url = sanitized.str();
        return result;
    }
};

// Middleware that processes OAuth callback behind nginx/haproxy
class OAuthCallbackHandler {
private:
    RedirectValidator validator_;
    std::string client_id_;
    std::string auth_endpoint_;

public:
    OAuthCallbackHandler(const RedirectConfig& config, const std::string& client_id,
                         const std::string& auth_endpoint)
        : validator_(config), client_id_(client_id), auth_endpoint_(auth_endpoint) {}

    std::string build_auth_redirect(const std::string& requested_redirect,
                                    const std::map<std::string, std::string>& headers) {
        auto validation = validator_.validate_redirect_uri(requested_redirect, headers);

        if (!validation.valid) {
            return "";
        }

        // Build the authorization URL with validated redirect_uri
        std::ostringstream auth_url;
        auth_url << auth_endpoint_
                 << "?client_id=" << client_id_
                 << "&redirect_uri=" << validation.sanitized_url
                 << "&response_type=code"
                 << "&scope=openid profile";

        return auth_url.str();
    }
};

} // namespace oauth

int main() {
    oauth::RedirectConfig config;
    config.allowed_domains = {"app.example.com", "auth.example.com"};
    config.allow_subdomains = true;
    config.allowed_schemes = {"https"};

    oauth::OAuthCallbackHandler handler(config, "my-client-id",
                                         "https://auth.example.com/authorize");

    // Simulate request from reverse proxy
    std::map<std::string, std::string> headers;
    headers["X-Forwarded-Proto"] = "https";
    headers["X-Forwarded-Host"] = "app.example.com";

    std::string redirect = handler.build_auth_redirect(
        "https://app.example.com/callback", headers);

    std::cout << "Auth URL: " << redirect << std::endl;
    return 0;
}
